class Solution {
public:
    void duplicateZeros(vector<int>& arr) {
        int n = arr.size();
        int zeros = 0, i = 0;
        while (i + zeros < n) {
            if (arr[i] == 0) {
                if (i + zeros == n - 1) {
                    arr[n - 1] = 0;
                    n--;
                    break;
                }
                zeros++;
            }
            i++;
        }
        int last = i - 1;
        for (int j = last; j >= 0; --j) {
            if (arr[j] == 0) {
                arr[j + zeros] = 0;
                zeros--;
                arr[j + zeros] = 0;
            } else {
                arr[j + zeros] = arr[j];
            }
        }
    }
};

